/* global figma */
// GENERATED by scripts/figma/build-plugin.cjs from design/tokens.json + design.pen(SCREEN_IDS 프레임) — 직접 수정하지 말고 `pnpm figma:build`를 실행한다.
// Figma 데스크톱 앱: Plugins → Development → Import plugin from manifest… → scripts/figma/manifest.json → 실행.
const TOKENS = __TOKENS__;
const ICONS = __ICONS__;
const IMAGES = __IMAGES__;
const SCREENS = __SCREENS__;
const FONT_CANDIDATES = ["Pretendard", "Noto Sans KR", "Inter"];
const WEIGHT_STYLES = { 400: ["Regular"], 500: ["Medium"], 600: ["SemiBold", "Semi Bold"], 700: ["Bold"] };

let fontFamily = "Inter";
let mode = "light";
const loadedFonts = new Map();
const colorVars = { light: {}, dark: {} };
const textStyles = {};
let colorCollection = null;
let darkModeId = null;

function hexToRgb(hex) {
  const n = parseInt(hex.replace("#", "").slice(0, 6), 16);
  return { r: ((n >> 16) & 255) / 255, g: ((n >> 8) & 255) / 255, b: (n & 255) / 255 };
}

function solid(hex, opacity) {
  const paint = { type: "SOLID", color: hexToRgb(hex) };
  if (opacity !== undefined) paint.opacity = opacity;
  return paint;
}

function colorPaint(name, opacity) {
  const hex = TOKENS.colors[mode][name];
  if (!hex) throw new Error(`알 수 없는 색 토큰: ${name}`);
  let paint = solid(hex, opacity);
  const variable = colorVars[mode][name];
  if (variable) {
    try {
      paint = figma.variables.setBoundVariableForPaint(paint, "color", variable);
    } catch (error) {
      console.warn("변수 바인딩 실패", name, error);
    }
  }
  return paint;
}

async function pickFontFamily() {
  const fonts = await figma.listAvailableFontsAsync();
  const families = new Set(fonts.map((f) => f.fontName.family));
  return FONT_CANDIDATES.find((c) => families.has(c)) || "Inter";
}

async function font(weight) {
  const key = String(weight);
  if (loadedFonts.has(key)) return loadedFonts.get(key);
  for (const style of [...WEIGHT_STYLES[key], "Regular"]) {
    const name = { family: fontFamily, style };
    try {
      await figma.loadFontAsync(name);
      loadedFonts.set(key, name);
      return name;
    } catch (error) {
      continue;
    }
  }
  throw new Error(`${fontFamily} 서체를 불러올 수 없습니다`);
}

function frame(name, o = {}) {
  const f = figma.createFrame();
  f.name = name;
  f.fills = o.fill ? [colorPaint(o.fill, o.fillOpacity)] : [];
  f.clipsContent = o.clip === true;
  if (o.layout) {
    f.layoutMode = o.layout;
    f.primaryAxisSizingMode = "AUTO";
    f.counterAxisSizingMode = "AUTO";
    f.itemSpacing = o.gap || 0;
    const p = o.padding || [0, 0, 0, 0];
    f.paddingTop = p[0];
    f.paddingRight = p[1];
    f.paddingBottom = p[2];
    f.paddingLeft = p[3];
    if (o.justify) f.primaryAxisAlignItems = o.justify;
    if (o.align) f.counterAxisAlignItems = o.align;
  }
  if (o.radius !== undefined) f.cornerRadius = o.radius;
  if (o.stroke) {
    f.strokes = [colorPaint(o.stroke)];
    f.strokeWeight = o.strokeWeight || 1;
  }
  return f;
}

function add(parent, node, o = {}) {
  parent.appendChild(node);
  const canHug = node.type === "TEXT" || (node.layoutMode !== undefined && node.layoutMode !== "NONE");
  const w = o.w === undefined ? "HUG" : o.w;
  const h = o.h === undefined ? "HUG" : o.h;
  if (typeof w === "number") {
    node.resize(w, node.height);
    node.layoutSizingHorizontal = "FIXED";
  } else if (w === "FILL" || canHug) {
    node.layoutSizingHorizontal = w;
  }
  if (typeof h === "number") {
    node.resize(node.width, h);
    node.layoutSizingVertical = "FIXED";
  } else if (h === "FILL" || canHug) {
    node.layoutSizingVertical = h;
  }
  return node;
}

async function text(content, tokenName, colorName, o = {}) {
  const ty = TOKENS.typography[tokenName];
  if (!ty) throw new Error(`알 수 없는 타이포 토큰: ${tokenName}`);
  const t = figma.createText();
  t.name = o.name || content;
  t.fontName = await font(ty.fontWeight);
  t.characters = content;
  t.fontSize = ty.fontSize;
  t.lineHeight = { value: ty.lineHeight, unit: "PIXELS" };
  t.letterSpacing = { value: ty.letterSpacing, unit: "PIXELS" };
  t.fills = [colorPaint(colorName, o.opacity)];
  if (o.align) t.textAlignHorizontal = o.align;
  t.textAutoResize = "WIDTH_AND_HEIGHT";
  const style = textStyles[tokenName];
  if (style) {
    try {
      await t.setTextStyleIdAsync(style.id);
    } catch (error) {
      t.textStyleId = style.id;
    }
  }
  return t;
}

async function textFill(parent, content, tokenName, colorName, o = {}) {
  const t = await text(content, tokenName, colorName, o);
  parent.appendChild(t);
  t.textAutoResize = "HEIGHT";
  t.layoutSizingHorizontal = "FILL";
  return t;
}

// ---------- Variables · Styles ----------
function createColorCollection() {
  const collection = figma.variables.createVariableCollection("color");
  const lightId = collection.modes[0].modeId;
  collection.renameMode(lightId, "light");
  let darkId = null;
  let darkCollection = null;
  try {
    darkId = collection.addMode("dark");
  } catch (error) {
    darkCollection = figma.variables.createVariableCollection("color/dark");
    darkCollection.renameMode(darkCollection.modes[0].modeId, "dark");
    figma.notify("이 플랜은 컬렉션당 모드 1개라 다크 값을 별도 컬렉션 color/dark에 만듭니다", { timeout: 4000 });
  }
  for (const name of Object.keys(TOKENS.colors.light)) {
    const v = figma.variables.createVariable(name, collection, "COLOR");
    v.setValueForMode(lightId, { ...hexToRgb(TOKENS.colors.light[name]), a: 1 });
    colorVars.light[name] = v;
    if (darkId) {
      v.setValueForMode(darkId, { ...hexToRgb(TOKENS.colors.dark[name]), a: 1 });
      colorVars.dark[name] = v;
    } else {
      const d = figma.variables.createVariable(name, darkCollection, "COLOR");
      d.setValueForMode(darkCollection.modes[0].modeId, { ...hexToRgb(TOKENS.colors.dark[name]), a: 1 });
      colorVars.dark[name] = d;
    }
  }
  return { collection, darkId, darkCollection };
}

function createFloatCollection(name, values) {
  const collection = figma.variables.createVariableCollection(name);
  const modeId = collection.modes[0].modeId;
  for (const [key, value] of Object.entries(values)) {
    const v = figma.variables.createVariable(key, collection, "FLOAT");
    v.setValueForMode(modeId, value);
  }
}

function createPaintStyles() {
  for (const m of ["light", "dark"]) {
    for (const [name, hex] of Object.entries(TOKENS.colors[m])) {
      const style = figma.createPaintStyle();
      style.name = `color/${m}/${name}`;
      style.paints = [solid(hex)];
    }
  }
}

async function createTextStyles() {
  for (const [name, ty] of Object.entries(TOKENS.typography)) {
    const style = figma.createTextStyle();
    style.name = `text/${name}`;
    style.fontName = await font(ty.fontWeight);
    style.fontSize = ty.fontSize;
    style.lineHeight = { value: ty.lineHeight, unit: "PIXELS" };
    style.letterSpacing = { value: ty.letterSpacing, unit: "PIXELS" };
    textStyles[name] = style;
  }
}

// ---------- Foundations 프레임 ----------
const COLOR_GROUPS = {
  SURFACE: ["background", "foreground", "card", "card-foreground", "popover", "popover-foreground", "border", "input", "ring"],
  BRAND: ["primary", "primary-foreground", "secondary", "secondary-foreground", "accent", "accent-foreground", "muted", "muted-foreground", "inverse", "inverse-foreground"],
  SEMANTIC: ["destructive", "destructive-foreground", "destructive-muted", "positive", "positive-foreground", "positive-muted", "warning", "warning-foreground", "warning-muted"],
  "SEMANTIC 2 / FIXED": ["info", "info-foreground", "info-muted", "highlight", "highlight-foreground", "white", "black"],
};

async function buildColorStyleFrame() {
  const root = frame("Color style / tokens", { layout: "VERTICAL", gap: 24, padding: [32, 32, 32, 32], fill: "white", radius: 16 });
  add(root, await text("Color style / tokens — design/tokens.json semantic.color", "h1", "foreground"));
  for (const m of ["light", "dark"]) {
    mode = m;
    const section = add(root, frame(`Mode / ${m}`, { layout: "VERTICAL", gap: 16, padding: [24, 24, 24, 24], fill: "background", radius: 15, stroke: "border" }));
    add(section, await text(m.toUpperCase(), "h3", "foreground"));
    for (const [group, names] of Object.entries(COLOR_GROUPS)) {
      add(section, await text(group, "caption", "muted-foreground"));
      const row = add(section, frame(`Row ${group}`, { layout: "HORIZONTAL", gap: 12 }));
      for (const name of names) {
        const swatch = add(row, frame(name, { layout: "VERTICAL", gap: 6 }), { w: 104 });
        add(swatch, frame("swatch", { fill: name, radius: 10, stroke: "border" }), { w: "FILL", h: 56 });
        await textFill(swatch, name, "caption", "foreground");
      }
    }
  }
  mode = "light";
  return root;
}

async function buildTextStyleFrame() {
  const root = frame("Text style / tokens", { layout: "VERTICAL", gap: 20, padding: [32, 32, 32, 32], fill: "background", radius: 16 });
  root.resize(900, root.height);
  root.counterAxisSizingMode = "FIXED";
  add(root, await text("Text style / tokens — design/tokens.json semantic.typography", "h1", "foreground"));
  const samples = TOKENS.samples;
  for (const [name, ty] of Object.entries(TOKENS.typography)) {
    const row = add(root, frame(`Row ${name}`, { layout: "HORIZONTAL", gap: 24, align: "CENTER", padding: [12, 0, 12, 0] }), { w: "FILL" });
    const meta = add(row, frame("Meta", { layout: "VERTICAL", gap: 4 }), { w: 160 });
    add(meta, await text(`text-${name}`, "label", "primary"));
    add(meta, await text(`${ty.fontSize}/${ty.lineHeight} · ${ty.fontWeight} · ${ty.letterSpacing}`, "caption", "muted-foreground"));
    await textFill(row, samples[name] || name, name, "foreground");
  }
  return root;
}

// ---------- design.pen 화면 → Figma 노드 (범용 변환) ----------
// 킷 화면은 layout: none(절대 좌표)·숫자 크기, home 아트보드는 auto-layout·fill_container·변수 참조·lucide icon 노드다. 둘 다 여기서 처리한다.
// frame/rectangle/ellipse/text/path/group/icon 7종을 변환한다. `$color` 참조는 Figma 변수에 바인딩하고, theme.mode가 dark인 프레임은 다크 모드로 고정한다.
const WEIGHT_NAMES = { normal: 400, bold: 700 };
const PRIMARY_ALIGN = { start: "MIN", center: "CENTER", end: "MAX", space_between: "SPACE_BETWEEN", space_around: "SPACE_BETWEEN" };
const COUNTER_ALIGN = { start: "MIN", center: "CENTER", end: "MAX" };
const penFontCache = new Map();
const penWarnings = [];
let hexToVar = null;

function warn(message) {
  penWarnings.push(message);
  console.warn(message);
}

// `#hex` 또는 `$변수` → 현재 모드의 hex
function penColorValue(value) {
  if (typeof value === "string" && value.startsWith("$")) {
    const hex = TOKENS.colors[mode][value.slice(1)];
    if (!hex) throw new Error(`알 수 없는 색 변수: ${value}`);
    return hex;
  }
  return value;
}

function penHex(value) {
  const h = penColorValue(value).replace("#", "");
  const full = h.length === 3 ? h.split("").map((c) => c + c).join("") : h;
  const n = parseInt(full.slice(0, 6), 16);
  const rgb = { r: ((n >> 16) & 255) / 255, g: ((n >> 8) & 255) / 255, b: (n & 255) / 255 };
  const a = full.length === 8 ? parseInt(full.slice(6, 8), 16) / 255 : 1;
  return { rgb, a, hex6: `#${full.slice(0, 6).toUpperCase()}` };
}

function penFills(value) {
  const list = value === undefined ? [] : Array.isArray(value) ? value : [value];
  return list.filter((f) => f !== undefined && (typeof f === "string" || f.enabled !== false));
}

function bindPaint(paint, varName) {
  const variable = colorVars[mode][varName];
  if (!variable) return paint;
  try {
    return figma.variables.setBoundVariableForPaint(paint, "color", variable);
  } catch (error) {
    console.warn("변수 바인딩 실패", varName, error);
    return paint;
  }
}

// `$변수`는 그 변수에, 킷의 raw hex는 토큰 값과 1:1로 일치할 때만 바인딩한다(흰색처럼 여러 토큰이 공유하는 값은 바인딩하지 않는다).
function penColorPaint(fill) {
  if (typeof fill === "string") {
    const { rgb, a, hex6 } = penHex(fill);
    const paint = { type: "SOLID", color: rgb, opacity: a };
    if (fill.startsWith("$")) return bindPaint(paint, fill.slice(1));
    if (mode !== "light") return paint;
    if (!hexToVar) {
      hexToVar = {};
      const counts = {};
      for (const hex of Object.values(TOKENS.colors.light)) counts[hex] = (counts[hex] || 0) + 1;
      for (const [name, hex] of Object.entries(TOKENS.colors.light)) if (counts[hex] === 1) hexToVar[hex] = name;
    }
    return hexToVar[hex6] ? bindPaint(paint, hexToVar[hex6]) : paint;
  }
  if (fill.type === "color") return penColorPaint(fill.color);
  if (fill.type === "gradient") {
    const stops = (fill.colors || []).map((c) => {
      const { rgb, a } = penHex(c.color);
      return { position: c.position, color: { ...rgb, a } };
    });
    const type = fill.gradientType === "radial" ? "GRADIENT_RADIAL" : fill.gradientType === "angular" ? "GRADIENT_ANGULAR" : "GRADIENT_LINEAR";
    return { type, gradientTransform: [[0, 1, 0], [-1, 0, 1]], gradientStops: stops, opacity: fill.opacity === undefined ? 1 : fill.opacity };
  }
  if (fill.type === "image") {
    const hash = penImageHash(fill.url);
    if (!hash) {
      warn(`이미지 fill을 가져오지 못해 회색 플레이스홀더로 대체: ${fill.url || "(url 없음)"}`);
      return solid("#CACACA");
    }
    // Pencil fill(cover)·fit(contain)·stretch → Figma FILL·FIT·CROP(기본 변환 = 노드 크기로 늘림)
    const scaleMode = fill.mode === "fit" ? "FIT" : fill.mode === "stretch" ? "CROP" : "FILL";
    return { type: "IMAGE", imageHash: hash, scaleMode, opacity: fill.opacity === undefined ? 1 : fill.opacity };
  }
  warn(`지원하지 않는 fill 종류: ${fill.type}`);
  return null;
}

// 같은 파일은 한 번만 Figma 이미지로 만든다. 실패도 기억해 경고를 반복하지 않는다(null).
const penImageHashes = new Map();
function penImageHash(url) {
  if (!url || !IMAGES[url]) return null;
  if (!penImageHashes.has(url)) {
    try {
      penImageHashes.set(url, figma.createImage(figma.base64Decode(IMAGES[url])).hash);
    } catch (error) {
      warn(`이미지 생성 실패: ${url} — ${error && error.message ? error.message : error}`);
      penImageHashes.set(url, null);
    }
  }
  return penImageHashes.get(url);
}

function penPaints(value) {
  return penFills(value).map(penColorPaint).filter(Boolean);
}

function penEffects(value) {
  const list = value === undefined ? [] : Array.isArray(value) ? value : [value];
  const out = [];
  for (const e of list) {
    if (e.enabled === false) continue;
    if (e.type === "shadow") {
      const { rgb, a } = penHex(e.color || "#00000040");
      out.push({
        type: e.shadowType === "inner" ? "INNER_SHADOW" : "DROP_SHADOW",
        color: { ...rgb, a },
        offset: { x: e.offset ? e.offset.x : 0, y: e.offset ? e.offset.y : 0 },
        radius: e.blur || 0,
        spread: e.spread || 0,
        visible: true,
        blendMode: "NORMAL",
      });
    } else if (e.type === "blur") {
      out.push({ type: "LAYER_BLUR", radius: e.radius || 0, visible: true });
    } else if (e.type === "background_blur") {
      out.push({ type: "BACKGROUND_BLUR", radius: e.radius || 0, visible: true });
    } else {
      warn(`지원하지 않는 effect: ${e.type}`);
    }
  }
  return out;
}

function applyStroke(node, n) {
  const paints = penPaints(n.stroke);
  if (paints.length === 0) return;
  node.strokes = paints;
  const w = n.strokeWidth === undefined ? 1 : n.strokeWidth;
  node.strokeWeight = typeof w === "object" ? Math.max(w.top || 0, w.right || 0, w.bottom || 0, w.left || 0) : w;
  if (n.strokeAlignment === "inner") node.strokeAlign = "INSIDE";
  else if (n.strokeAlignment === "outer") node.strokeAlign = "OUTSIDE";
  else node.strokeAlign = "CENTER";
  if (n.strokeLinecap) node.strokeCap = n.strokeLinecap === "round" ? "ROUND" : n.strokeLinecap === "square" ? "SQUARE" : "NONE";
  if (n.strokeLinejoin) node.strokeJoin = n.strokeLinejoin === "round" ? "ROUND" : n.strokeLinejoin === "bevel" ? "BEVEL" : "MITER";
}

function applyCorner(node, n) {
  if (n.cornerRadius === undefined) return;
  if (Array.isArray(n.cornerRadius)) {
    node.topLeftRadius = n.cornerRadius[0];
    node.topRightRadius = n.cornerRadius[1];
    node.bottomRightRadius = n.cornerRadius[2];
    node.bottomLeftRadius = n.cornerRadius[3];
  } else {
    node.cornerRadius = n.cornerRadius;
  }
}

function applyLayout(node, n) {
  const layout = n.layout === undefined ? "horizontal" : n.layout; // Pencil 프레임 기본값은 horizontal
  if (layout === "none") {
    node.layoutMode = "NONE";
    return;
  }
  node.layoutMode = layout === "vertical" ? "VERTICAL" : "HORIZONTAL";
  node.primaryAxisSizingMode = "AUTO";
  node.counterAxisSizingMode = "AUTO";
  node.itemSpacing = typeof n.gap === "number" ? n.gap : 0;
  const p = n.padding === undefined ? 0 : n.padding;
  const [top, right, bottom, left] = typeof p === "number" ? [p, p, p, p] : p.length === 2 ? [p[0], p[1], p[0], p[1]] : p;
  node.paddingTop = top;
  node.paddingRight = right;
  node.paddingBottom = bottom;
  node.paddingLeft = left;
  node.primaryAxisAlignItems = PRIMARY_ALIGN[n.justifyContent] || "MIN";
  node.counterAxisAlignItems = COUNTER_ALIGN[n.alignItems] || "MIN";
}

function safeResize(node, w, h) {
  const cw = typeof w === "number" ? Math.max(w, 0.01) : node.width;
  const ch = typeof h === "number" ? Math.max(h, 0.01) : node.height;
  node.resize(cw, ch);
}

function isAutoLayout(node) {
  return node !== null && node !== undefined && node.layoutMode !== undefined && node.layoutMode !== "NONE";
}

function inParentLayout(parent, n) {
  return isAutoLayout(parent) && n.layoutPosition !== "absolute";
}

function penSizing(v) {
  if (typeof v === "number") return v;
  if (typeof v === "string" && v.indexOf("fill_container") === 0) return "FILL";
  return "HUG"; // fit_content 또는 미지정
}

// 부모에 붙이고 Pencil 크기 규칙(숫자 / fill_container / fit_content)을 Figma 사이징으로 옮긴다
function place(parent, node, n) {
  parent.appendChild(node);
  const inLayout = inParentLayout(parent, n);
  if (n.layoutPosition === "absolute" && isAutoLayout(parent)) node.layoutPositioning = "ABSOLUTE";
  const self = isAutoLayout(node);
  const canHug = node.type === "TEXT" || self;
  const w = penSizing(n.width);
  const h = penSizing(n.height);
  if (typeof w === "number") {
    safeResize(node, w, node.height);
    if (inLayout || self) node.layoutSizingHorizontal = "FIXED";
  } else if (w === "FILL" && inLayout) {
    if (node.type === "TEXT") node.textAutoResize = node.textAutoResize === "NONE" ? "NONE" : "HEIGHT";
    node.layoutSizingHorizontal = "FILL";
  } else if (canHug && (inLayout || self)) {
    node.layoutSizingHorizontal = "HUG";
  }
  if (typeof h === "number") {
    safeResize(node, node.width, h);
    if (inLayout || self) node.layoutSizingVertical = "FIXED";
  } else if (h === "FILL" && inLayout) {
    node.layoutSizingVertical = "FILL";
  } else if (canHug && (inLayout || self)) {
    node.layoutSizingVertical = "HUG";
  }
  return node;
}

// 회전(좌상단 기준, CCW)과 flip을 적용한다. Figma의 rotation도 원점(좌상단) 기준 CCW다. auto-layout 자식은 위치를 부모가 정한다.
function applyTransform(node, n, parent) {
  if (inParentLayout(parent, n)) return;
  node.x = n.x || 0;
  node.y = n.y || 0;
  if (n.rotation) node.rotation = n.rotation;
  if (!n.flipX && !n.flipY) return;
  const [[a, b, tx], [c, d, ty]] = node.relativeTransform;
  const w = node.width;
  const h = node.height;
  let m = [[a, b, tx], [c, d, ty]];
  if (n.flipY) m = [[m[0][0], -m[0][1], m[0][1] * h + m[0][2]], [m[1][0], -m[1][1], m[1][1] * h + m[1][2]]];
  if (n.flipX) m = [[-m[0][0], m[0][1], m[0][0] * w + m[0][2]], [-m[1][0], m[1][1], m[1][0] * w + m[1][2]]];
  node.relativeTransform = m;
}

function applyCommon(node, n) {
  node.name = n.name || n.type;
  if (n.opacity !== undefined) node.opacity = n.opacity;
  if (n.enabled === false) node.visible = false;
  if ("effects" in node && n.effect !== undefined) node.effects = penEffects(n.effect);
  try {
    node.setPluginData("penId", n.id);
  } catch (error) {
    // 플러그인 데이터는 추적용이라 실패해도 무시한다
  }
}

async function penFont(family, weightValue, style) {
  const weight = typeof weightValue === "number" ? weightValue : WEIGHT_NAMES[weightValue] || Number(weightValue) || 400;
  const italic = style === "italic";
  const key = `${family}|${weight}|${italic}`;
  if (penFontCache.has(key)) return penFontCache.get(key);
  const styles = (WEIGHT_STYLES[String(weight)] || [weight >= 800 ? "Black" : "Regular"]).slice();
  if (weight >= 800) styles.unshift("Black", "ExtraBold", "Extra Bold");
  const candidates = [];
  for (const fam of [family, fontFamily, ...FONT_CANDIDATES]) {
    for (const s of styles) candidates.push({ family: fam, style: italic ? `${s} Italic` : s });
    candidates.push({ family: fam, style: italic ? "Italic" : "Regular" });
  }
  for (const name of candidates) {
    try {
      await figma.loadFontAsync(name);
      if (name.family !== family) warn(`서체 대체: ${family} ${weight} → ${name.family} ${name.style}`);
      penFontCache.set(key, name);
      return name;
    } catch (error) {
      continue;
    }
  }
  throw new Error(`서체를 불러올 수 없습니다: ${family} ${weight}`);
}

async function buildPenText(n) {
  const t = figma.createText();
  t.fontName = await penFont(n.fontFamily || fontFamily, n.fontWeight === undefined ? 400 : n.fontWeight, n.fontStyle);
  t.characters = String(n.content === undefined ? "" : n.content);
  t.fontSize = n.fontSize || 14;
  t.lineHeight = typeof n.lineHeight === "number" ? { value: n.lineHeight * 100, unit: "PERCENT" } : { unit: "AUTO" };
  if (typeof n.letterSpacing === "number") t.letterSpacing = { value: n.letterSpacing, unit: "PIXELS" };
  if (n.textAlign) t.textAlignHorizontal = { left: "LEFT", center: "CENTER", right: "RIGHT", justify: "JUSTIFIED" }[n.textAlign] || "LEFT";
  if (n.textAlignVertical) t.textAlignVertical = { top: "TOP", middle: "CENTER", bottom: "BOTTOM" }[n.textAlignVertical] || "TOP";
  if (n.underline) t.textDecoration = "UNDERLINE";
  else if (n.strikethrough) t.textDecoration = "STRIKETHROUGH";
  const growth = n.textGrowth || "auto";
  if (growth === "fixed-width" && typeof n.width === "number") {
    t.textAutoResize = "HEIGHT";
    safeResize(t, n.width, undefined);
  } else if (growth === "fixed-width-height" && typeof n.width === "number" && typeof n.height === "number") {
    t.textAutoResize = "NONE";
    safeResize(t, n.width, n.height);
  } else {
    t.textAutoResize = "WIDTH_AND_HEIGHT";
  }
  t.fills = penPaints(n.fill);
  return t;
}

function svgAttr(name, value) {
  return value === undefined || value === null ? "" : ` ${name}="${String(value).replace(/"/g, "&quot;")}"`;
}

// path는 SVG로 가져온 뒤 안쪽 벡터만 꺼내 Pencil의 위치·크기로 맞춘다(Pencil은 geometry의 tight bbox를 노드 박스에 매핑한다).
function buildPenPath(n) {
  const fills = penFills(n.fill);
  const strokes = penFills(n.stroke);
  const fillHex = fills.length ? (typeof fills[0] === "string" ? fills[0] : fills[0].color) : null;
  const strokeHex = strokes.length ? (typeof strokes[0] === "string" ? strokes[0] : strokes[0].color) : null;
  const f = fillHex ? penHex(fillHex) : null;
  const s = strokeHex ? penHex(strokeHex) : null;
  const viewBox = n.viewBox ? ` viewBox="${n.viewBox.join(" ")}"` : "";
  const size = viewBox && typeof n.width === "number" && typeof n.height === "number" ? ` width="${n.width}" height="${n.height}"` : "";
  const svg =
    `<svg xmlns="http://www.w3.org/2000/svg"${viewBox}${size}><path` +
    svgAttr("d", n.geometry || "") +
    svgAttr("fill", f ? f.hex6 : "none") +
    (f && f.a < 1 ? svgAttr("fill-opacity", f.a) : "") +
    svgAttr("fill-rule", n.fillRule) +
    (s ? svgAttr("stroke", s.hex6) + (s.a < 1 ? svgAttr("stroke-opacity", s.a) : "") + svgAttr("stroke-width", n.strokeWidth === undefined ? 1 : n.strokeWidth) : "") +
    svgAttr("stroke-linecap", n.strokeLinecap) +
    svgAttr("stroke-linejoin", n.strokeLinejoin) +
    "/></svg>";
  const wrapper = figma.createNodeFromSvg(svg);
  let shape;
  if (wrapper.children.length === 1) shape = wrapper.children[0];
  else if (wrapper.children.length > 1) shape = figma.group(wrapper.children.slice(), wrapper);
  else {
    warn(`빈 path: ${n.name} (${n.id})`);
    return { wrapper, shape: null };
  }
  // 토큰과 일치하는 색은 변수에 바인딩(SVG 가져오기는 raw 색만 남기므로 다시 칠한다)
  if (shape.type === "VECTOR") {
    if (fills.length) shape.fills = penPaints(n.fill);
    if (strokes.length) shape.strokes = penPaints(n.stroke);
  }
  return { wrapper, shape };
}

// lucide icon 노드: 아이콘 SVG를 가져와 벡터의 stroke/fill을 색 변수에 바인딩한다
function buildPenIcon(n) {
  const svg = ICONS[n.icon];
  if (!svg) throw new Error(`알 수 없는 아이콘: ${n.icon} (${n.id})`);
  const size = typeof n.width === "number" ? n.width : 24;
  const fill = penFills(n.fill)[0];
  const hex = fill ? penHex(typeof fill === "string" ? fill : fill.color).hex6 : TOKENS.colors[mode].foreground;
  const node = figma.createNodeFromSvg(svg.replace(/currentColor/g, hex).replace(/__SIZE__/g, String(size)));
  node.name = `icon: ${n.icon}`;
  if (fill) {
    const paint = penColorPaint(fill);
    const paintVectors = (parent) => {
      for (const child of parent.children || []) {
        if ("strokes" in child && child.strokes.length) child.strokes = [paint];
        if ("fills" in child && child.fills.length && child.type !== "FRAME") child.fills = [paint];
        if (child.children) paintVectors(child);
      }
    };
    paintVectors(node);
  }
  return node;
}

const penErrors = [];

// 노드 하나가 실패해도 가져오기를 멈추지 않는다. 실패는 Import log에 남긴다.
async function buildPenNode(n, parent) {
  const prevMode = mode;
  if (n.theme && n.theme.mode) mode = n.theme.mode === "dark" ? "dark" : "light";
  let node = null;
  try {
    node = await buildPenNodeInner(n, parent);
  } catch (error) {
    const message = `${n.type} "${n.name || ""}" (${n.id}): ${error && error.message ? error.message : String(error)}`;
    penErrors.push(message);
    console.error("노드 변환 실패", message, error);
  } finally {
    mode = prevMode;
  }
  if (node && n.theme && n.theme.mode === "dark" && darkModeId && colorCollection) {
    try {
      node.setExplicitVariableModeForCollection(colorCollection, darkModeId);
    } catch (error) {
      console.warn("다크 모드 지정 실패", n.name, error);
    }
  }
  return node;
}

async function buildPenNodeInner(n, parent) {
  let node;
  switch (n.type) {
    case "frame": {
      node = figma.createFrame();
      applyLayout(node, n);
      node.fills = penPaints(n.fill);
      node.clipsContent = n.clip === true;
      applyCorner(node, n);
      applyStroke(node, n);
      place(parent, node, n);
      // 이름·위치를 먼저 적용해 자식 변환이 실패해도 부분 결과가 제자리에 남게 한다
      applyCommon(node, n);
      applyTransform(node, n, parent);
      for (const child of n.children || []) await buildPenNode(child, node);
      return node;
    }
    case "group": {
      // 그룹은 임시 프레임에 자식을 만든 뒤 그 안에서 그룹으로 묶고 부모로 옮긴다. 회전·flip이 있으면 원점 보존을 위해 프레임으로 남긴다.
      const temp = figma.createFrame();
      temp.name = n.name || "group";
      temp.layoutMode = "NONE";
      temp.fills = [];
      temp.clipsContent = false;
      parent.appendChild(temp);
      temp.x = n.x || 0;
      temp.y = n.y || 0;
      for (const child of n.children || []) await buildPenNode(child, temp);
      let maxX = 1;
      let maxY = 1;
      for (const c of temp.children) {
        maxX = Math.max(maxX, c.x + c.width);
        maxY = Math.max(maxY, c.y + c.height);
      }
      temp.resize(Math.max(maxX, 0.01), Math.max(maxY, 0.01));
      const keepFrame = Boolean(n.rotation) || n.flipX || n.flipY || temp.children.length === 0 || isAutoLayout(parent);
      if (keepFrame) {
        node = temp;
      } else {
        try {
          const group = figma.group(temp.children.slice(), temp);
          const index = parent.children.indexOf(temp);
          parent.insertChild(index < 0 ? parent.children.length : index, group);
          group.x += temp.x;
          group.y += temp.y;
          temp.remove();
          node = group;
        } catch (error) {
          warn(`그룹 생성 실패, 프레임으로 유지: ${n.name} (${error.message})`);
          node = temp;
        }
      }
      applyCommon(node, n);
      if (node === temp) applyTransform(node, n, parent);
      return node;
    }
    case "rectangle": {
      node = figma.createRectangle();
      node.fills = penPaints(n.fill);
      applyCorner(node, n);
      applyStroke(node, n);
      place(parent, node, n);
      break;
    }
    case "ellipse": {
      node = figma.createEllipse();
      node.fills = penPaints(n.fill);
      applyStroke(node, n);
      const sweep = n.sweepAngle === undefined ? 360 : n.sweepAngle;
      if (Math.abs(Math.abs(sweep) - 360) > 0.01 || n.innerRadius) {
        const start = ((n.startAngle || 0) * Math.PI) / 180;
        node.arcData = { startingAngle: -start, endingAngle: -start - (sweep * Math.PI) / 180, innerRadius: n.innerRadius || 0 };
      }
      place(parent, node, n);
      break;
    }
    case "text": {
      node = await buildPenText(n);
      place(parent, node, n);
      break;
    }
    case "icon": {
      node = buildPenIcon(n);
      place(parent, node, n);
      break;
    }
    case "path": {
      const { wrapper, shape } = buildPenPath(n);
      if (!shape) {
        node = wrapper;
        parent.appendChild(node);
        break;
      }
      parent.appendChild(shape);
      wrapper.remove();
      if (typeof n.width === "number" && typeof n.height === "number" && shape.width > 0.01 && shape.height > 0.01) {
        shape.resize(Math.max(n.width, 0.01), Math.max(n.height, 0.01));
      }
      node = shape;
      break;
    }
    default:
      warn(`지원하지 않는 노드 종류: ${n.type} (${n.name})`);
      return null;
  }
  applyCommon(node, n);
  applyTransform(node, n, parent);
  return node;
}

async function buildPenScreens(page) {
  const built = [];
  for (const screen of SCREENS.screens) {
    mode = "light";
    const node = await buildPenNode(screen, page);
    if (node) built.push(node);
  }
  return built;
}

// ---------- 실행 ----------
async function getOrCreatePage(name) {
  await figma.loadAllPagesAsync();
  let page = figma.root.children.find((p) => p.name === name);
  if (!page) {
    page = figma.createPage();
    page.name = name;
  }
  return page;
}

async function main() {
  fontFamily = await pickFontFamily();
  await font(400);
  const { collection, darkId } = createColorCollection();
  colorCollection = collection;
  darkModeId = darkId;
  createFloatCollection("radius", TOKENS.radius);
  createFloatCollection("size", TOKENS.size);
  createPaintStyles();
  await createTextStyles();

  const foundations = await getOrCreatePage("Foundations");
  const colorFrame = await buildColorStyleFrame();
  foundations.appendChild(colorFrame);
  colorFrame.x = 0;
  colorFrame.y = 0;
  const textFrame = await buildTextStyleFrame();
  foundations.appendChild(textFrame);
  textFrame.x = 0;
  textFrame.y = colorFrame.height + 120;

  const screens = await getOrCreatePage("Screens");
  await figma.setCurrentPageAsync(screens);
  // design.pen의 화면 12개(킷 10 + home·home/dark) — Pencil 좌표를 그대로 옮긴다(원점 = 화면들의 좌상단)
  const built = await buildPenScreens(screens);
  mode = "light";

  // 실패·경고 내역을 캔버스에 텍스트로 남긴다(콘솔을 열지 않아도 복사할 수 있게)
  if (penErrors.length || penWarnings.length) {
    const lines = [
      `Import log — 실패 ${penErrors.length} · 경고 ${penWarnings.length}`,
      ...penErrors.map((e) => `✗ ${e}`),
      ...penWarnings.map((w) => `△ ${w}`),
    ];
    const log = figma.createText();
    log.fontName = await font(400);
    log.characters = lines.join("\n");
    log.fontSize = 12;
    log.name = "Import log";
    log.fills = [solid(penErrors.length ? "#D32F2F" : "#898989")];
    screens.appendChild(log);
    log.textAutoResize = "WIDTH_AND_HEIGHT";
    log.x = 0;
    log.y = -Math.max(120, 16 * lines.length + 40);
    built.push(log);
  }
  figma.viewport.scrollAndZoomIntoView(built);
  const summary = `가져오기 완료 — 서체 ${fontFamily}, 변수 ${Object.keys(TOKENS.colors.light).length}색, 화면 ${built.length - (penErrors.length || penWarnings.length ? 1 : 0)}개`;
  if (penWarnings.length) console.warn(`경고 ${penWarnings.length}건`, penWarnings);
  if (penErrors.length) {
    console.error(`실패 ${penErrors.length}건`, penErrors);
    figma.notify(`${summary} · 실패 ${penErrors.length}건 — 첫 오류: ${penErrors[0].slice(0, 160)} (Screens 페이지 상단 Import log 참고)`, { timeout: 15000, error: true });
  } else {
    figma.notify(penWarnings.length ? `${summary} (경고 ${penWarnings.length}건 — Import log 참고)` : summary, { timeout: 6000 });
  }
}

main()
  .then(() => figma.closePlugin())
  .catch((error) => {
    console.error(error);
    figma.closePlugin(`가져오기 실패: ${error.message} — Plugins → Development → Open console 에서 스택을 확인한다`);
  });
